ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "status": 500,
  "code": "CONTACT_INFO",
  "message": {
    "message": "User already has registered contact information. Try updating it."
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

%dw 2.0
output application/json
import * from dw::core::Strings
var capitalizedPayloadArr = payload.data map(item, ind) -> item mapObject ((value, key, index) -> {
(capitalize("$key")) : value})
---
{
	Comunicaciones_Cobranza: {
		"Registro_Contacto": capitalizedPayloadArr,
		"Horario": p('customerContact.timeFrame'),
		"Fecha_Registro": now() >> "America/Bogota",
		"Fecha_Modificacion": now() >> "America/Bogota"
	}
}

%dw 2.0
output application/json
---
if (payload.matched == 1 and payload.modified == 1) {
	codigo: 200
}
else
{
  "status": 500,
  "code": "CONTACT_INFO",
  "message": {
    "message": "Unable to register contact information for that user"
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}
